import{_ as o,a,b as n}from"./chunks/zmp-cal-3.C9ishzoW.js";import{_ as i,o as r,c as e,a5 as l}from"./chunks/framework.DGp912Ge.js";const f=JSON.parse('{"title":"Calibration & Tuning","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/troubleshooting/calibration-tuning.md","filePath":"manual/troubleshooting/calibration-tuning.md","lastUpdated":1785806767000}'),s={name:"manual/troubleshooting/calibration-tuning.md"};function c(u,t,b,h,d,g){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="calibration-tuning" tabindex="-1">Calibration &amp; Tuning <a class="header-anchor" href="#calibration-tuning" aria-label="Permalink to &quot;Calibration &amp; Tuning&quot;">​</a></h1><p>You can perform <strong>ZMP calibration</strong> and <strong>various tuning</strong> in the app to improve the robot&#39;s walking stability and performance.</p><h2 id="zmp-calibration" tabindex="-1">ZMP Calibration <a class="header-anchor" href="#zmp-calibration" aria-label="Permalink to &quot;ZMP Calibration&quot;">​</a></h2><p>ZMP (Zero Moment Point) calibration aligns the center of ground reaction force while the robot is standing, so the robot can maintain balance during walking.</p><h3 id="preparation" tabindex="-1">Preparation <a class="header-anchor" href="#preparation" aria-label="Permalink to &quot;Preparation&quot;">​</a></h3><ul><li>Place the robot on a <strong>flat, solid surface</strong>.</li><li>Ensure there are no obstacles around the robot.</li><li>The RBQGUI app must be connected to the robot.</li></ul><h3 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;Procedure&quot;">​</a></h3><ol><li>Launch the <strong>RBQGUI</strong> app and connect to the robot.</li><li>Set the robot to <strong>Stance</strong> (standing) mode.</li><li>Press and hold the <strong>Sit</strong> button.</li></ol><figure><img src="'+o+'" alt="Sit button"></figure><ol start="4"><li>In the <strong>menu</strong>, select the <strong>ZMP CALIBRATE</strong> button.</li></ol><figure><img src="'+a+'" alt="ZMP CALIBRATE selection (Recovery menu)"></figure><ol start="5"><li>When the button turns <strong>orange</strong>, calibration is in progress.</li><li>Do not touch the robot until calibration is complete.</li></ol><figure><img src="'+n+'" alt="Calibration in progress (ZMP Init)"></figure><ol start="7"><li>When the button returns to <strong>white</strong> (default) and the display shows <strong>Gait: Stance</strong>, calibration is complete.</li><li>Move the robot and verify that the operation is normal.</li></ol><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Do not place objects on the robot or push the robot during calibration. If calibration fails, you may need to run it again.</p></div></div>',15)])])}const _=i(s,[["render",c]]);export{f as __pageData,_ as default};
